import{_ as s,O as a,o as r,c as i,a as o,i as n,f as c}from"./chunks/framework.fmIt2z2h.js";const f=JSON.parse('{"title":"D.03　研究设计、测量、因果与材料形成","description":"","frontmatter":{"title":"D.03　研究设计、测量、因果与材料形成","xkChars":718,"xkLessons":{"D.03":{"title":"D.03　研究设计、测量、因果与材料形成","lead":"一张批准率上升的表，不能同时告诉我们申请是否更容易、钱是否真的到手、生活是否改善。研究设计的第一步是写清要回答哪一个问题，再检查材料怎样产生，以及还兼容哪些解释。","explanation":["原文定位：第4561—4576行；原文锚点 section-d-03；短引文：‘总效应、特定中介、联合响应和报告机制应针对所问问题分别识别。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","随机实验、自然实验、观察研究、过程追踪、比较历史、口述与考古各能解决部分识别问题，不能靠方法名直接承诺全部结论。先写处理、比较对象、时间、结果和单位。例如被邀请参加项目的人，与实际参加的人不是同一处理与群体；实际参加者前后变化还可能受自选、时间趋势等影响；整个政策扩张有容量和相互影响，某个个体结果也不由群体平均直接给出。项目名称相同不能让这些估计目标互换。","总效应可以在相应假设下被识别，而具体中介尚未清楚；这时应保留总效应的有限答案，不因未穷尽微观机制就宣布一无所知。反过来，讲出若干机制或证明局部环节存在，不保证它们在同案、同一人群、同一窗口接成有净效果的整链。相抵通道、不同响应者和资源约束都可能改变终端结果。","控制当前状态可能排除共同原因，也可能切断想研究的历史形成通道，或因条件化共同结果引入选择偏差。因此控制变量不是越多越好。若H通过S影响Y，而给定S后H没有额外信息，要分别报告H对Y的总作用与在指定S表示后的条件残差。本节与G3相接时尤其不能把条件残差为零说成历史从未起作用，也不能只因存在历史作用就自动认定历史增量问题已经通过。","测量至少分对象、观测指标、构念与分类规则。对象是想认识的现象，指标是实际记录，构念是对潜在属性的理论表达，分类规则是按何标准分组。反映潜在状态的多个指标，需要检查它们怎样受该状态影响及误差；共同定义指数的组成项则涉及内容覆盖、权重和合成规则，不能机械套同一种效度论证。测验表现、潜在能力、资源条件与预测代理也不能因都变成数字就等同。","趋势取决于量尺、分母、测量方式及样本进入。批准率上升可能因为办理更容易，也可能申请者构成改变；公开检出数下降可能因为风险减少、响应避免事件或检出率下降。指标改善可能是真实进步、对狭窄目标的真实训练、样本选择或伪造，几种过程也能并存。方向相同不能裁定动机，不能看到好数字就宣布治理成功，也不能看到指标受激励就直接指控操纵。","原文申请流程例是教学构造。简化后批准率上升可以提示程序障碍减少，但生活保障还涉及实际给付、质量、等待和未申请者。若未申请者因障碍被排除，批准率可能越高越漏掉困难处境；需要明确分母和额外结果。局部程序成果如有支持可以保留，不因更终端结果未明而全部撤销。","档案没有异议仅在相关异议本应稳定留下、记录保存且能够访问的条件下才有对应反证力。无法表达、未被记录、记录被毁或尚未开放都可能导致沉默。同样，考古材料的年代、用途、所有者与实际权力是不同问题：测年可以支持时间定位，但不自动证明器物属于统治者；某种痕迹支持活动方式，也不一并说明完整制度。材料形成过程属于推断的一部分。","观测记录可看作对象状态经过采集、响应与报告过程形成的结果。若现有观测同时兼容多个生成过程，更多同样口径记录未必解决识别，需要能区分它们的新材料，例如独立测量、采集覆盖或响应时间。下面简化算例只显示不可区分性，不能当作真实疫情、政策或风险估计，也没有据此给出个人健康建议。","两段平均作用都为正，不代表平均数相乘就是整链。必须知道前段被改变的人是否也是后段会响应的人，前段输出与后段输入是否对应、时序与共同条件是否成立。正文§2.4.2给出两类人群反例，本讲明确重算它：类型0只发生前段变化，类型1只会对人为设置的中介响应，两段均值各为1/2却无人走通整链。","九个专题定位分别对应因果机制、研究设计、案例与过程历史、统计与不确定性、测量代理、指标受激励改变、复现与发表选择、档案口述沉默、考古物质材料。它们是研究入口，不是在一节中宣称所有方法争论已解决。最强反方担心区分太多导致永远无法结论；回应是保留任务真正被识别的答案，例如有据总效应、局部机制、范围界限或具体过程知识，停止的只是材料尚不能支持的额外断言。"],"distinctions":[{"leftTitle":"被邀请的平均效应","leftText":"关注获得邀请或机会这一处理。","rightTitle":"实际参加者的变化","rightText":"处理及选择人群不同，不能直接替代。"},{"leftTitle":"总效应","leftText":"指定干预对终端结果的整体作用。","rightTitle":"特定中介","rightText":"说明某通道怎样传递，需额外识别条件。"},{"leftTitle":"条件历史残差","leftText":"在指定当前表示S后H还有多少增量信息。","rightTitle":"历史总作用","rightText":"历史可已通过S形成结果，残差零不否定该作用。"},{"leftTitle":"反映性指标","leftText":"以潜在状态影响观测为解释关系。","rightTitle":"定义性合成项","rightText":"共同构成指数，权重覆盖与内容责任不同。"},{"leftTitle":"没有记录","leftText":"可能由多种采集保存访问过程导致。","rightTitle":"事件不存在","rightText":"需要记录本应存在且可发现的条件才有反证力。"}],"boundaries":["研究设计名称不自动识别所有机制，群体平均也不自动回答个体结果。","控制状态可能阻断中介或引入选择偏差，不是变量越多越可靠。","条件历史残差为零不证明历史无效，也不自动满足G3。","教学指标及整链算例不估计现实效果，真实案例原作者强表述不自动继承为现代识别结论。","原文研究入口03.01—03.09未提供全部研究原稿，本讲不据编号冒称全文核验。"],"questions":["为什么总效应明确仍可保留中介未决？","两段均值算例为何整链为零？","记录从20降10能确定检出率未变吗？","档案无异议什么时候才有反证力？"],"diagramPath":"/reading-assets/S-D-03/figures/section-d-03.png","caseLinks":[{"title":"真实研究记录：Snow追查发病住址与供水来源","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"caseNotes":[{"title":"真实研究记录：Snow追查发病住址与供水来源","text":"Snow1855年第二版记述1854年伦敦供水调查时，说明被移送者须追查发病时住所；住户常不能直接说清供水公司，故结合账单与化学检测核来源。他还说明四周调查中有供水未查明的记录。这里的材料不是天然完成的数据表，而经过住址、暴露分类与缺失处理形成。","sourceLabel":"John Snow, On the Mode of Communication of Cholera，1855第二版原著转录","sourceUrl":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","sourceLocator":"原书印刷pp77—80：In cases where persons had been removed…；The inquiry was necessarily…；化学核验段；Of these it was ascertained…末项","boundary":"只据作者原始调查叙述说明数据形成和缺失，不凭此认定随机分配、完整中介或现代无混杂识别；未复现历史调查，不引用其化学数值作当前操作建议。","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"sourceRefs":[{"section":"D.03","start_line":4561,"end_line":4576,"startLine":4561,"endLine":4576}],"outputId":"section-d-03","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["登记处理、比较、时间、结果和单位，区分邀请、参加、政策与个体目标。","检查设计为何识别目标及其假设，分别评价总效应与中介和联合响应。","说明指标与构念、量尺分母、样本及记录生成过程，列竞争解释。","对档案沉默和物质痕迹核应有记录、保存可及及具体推断范围。","无法区分时保留多个解释和有据局部答案，规划区分性材料，不由故事或指标方向填满整链。"],"teachingExamples":[{"title":"原文教学例展开：批准不等于保障","text":"假想流程简化后申请批准率上升。要判断保障是否改善，另查批准后实际给付、服务质量和未申请群体；不能只把获批当作资源已到位。若仅有批准资料，可限称审批结果变化，程序障碍解释还需生成过程证据。","assumptions":"按原文教学例展开，无真实项目数据。","boundary":"不虚构因果估计或补贴成效。"},{"title":"数学教学构造：两段均值相乘失败","text":"按正文§2.4.2设两类s∈{0,1}等权，处理a∈{0,1}，中介m(a)=a(1−s)，结果y(a,m)=sm。类型0的处理使m增加1但y始终0；类型1的m不受a影响，但若直接设置m从0到1，y增加1。因此平均a→m作用=1/2、平均设置m→y作用=1/2，乘积=1/4；实际y(a,m(a))两类均恒0，整链效应=0。","assumptions":"所有函数与等权结构均为明确形式构造，没有现实观测。","boundary":"只反驳无联合条件就相乘的普遍推论，不否定独立设计可以识别真实总效应。"},{"title":"数学教学构造：同样十条记录，三种过程","text":"设100个机会，基准风险0.2、检出率1、无预防时预期记录20条。A风险降至0.1、其他不变，预期10条；B风险仍0.2但检出率降0.5，也为10；C风险仍0.2、检出率1但响应避免一半事件，仍为10。简化期望式100×风险×未被避免比例×检出率不能凭结果10识别究竟发生哪种过程。","assumptions":"独立同质机会、无假阳性、各比例确定，均为教学假设；计数为期望值不是实测。","boundary":"现实中过程可依赖且更复杂，算例不估计任何风险或医疗效果。"},{"title":"数学教学构造：历史作用已经进入当前状态","text":"设二元H，结构方程S=H、Y=S。改变H从0到1使Y由0到1，历史总作用为1；但知道S就完全知道Y，H在S之外没有额外预测信息。不能把条件增量零解释为历史无作用，也不能把总作用1自动当作G3增量为正。","assumptions":"确定性结构方程纯教学；明确干预含义且无其他路径。","boundary":"由于H与S确定对应，不能据观察数据擅称一般现实直接效应已识别。"}],"counterexamples":[{"identity":"source_counterexample","text":"H在控制S后不显著，所以过去没有造成当前结果。","effect":"须区别总作用与条件残差；控制S可能截断历史形成通道。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"两段均值都为正，相乘必得正的整链效应。","effect":"联合响应可能不重合，明确函数反例给出整链为零。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"阳性公开记录下降，真实风险必然下降。","effect":"采集检出与响应过程也能产生同方向记录变化，需区分性材料。","sourceIds":["theory"]}],"questionAnswers":[{"question":"为什么总效应明确仍可保留中介未决？","answer":"设计可能识别指定总作用但未区分传递通道，不能强补机制，也不应撤掉独立总效应。","basis":"本节原文及上述公开推导"},{"question":"两段均值算例为何整链为零？","answer":"前段有效的是类型0，后段响应的是类型1，没有类型同时走通两段。","basis":"本节原文及上述公开推导"},{"question":"记录从20降10能确定检出率未变吗？","answer":"不能，数值相同兼容不同生成过程，需要独立采集与响应材料。","basis":"本节原文及上述公开推导"},{"question":"档案无异议什么时候才有反证力？","answer":"异议若发生本应稳定被记录、记录保存并可访问，且相关生成条件得到支持时。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-03/figures/section-d-03.png","alt":"固定估计目标，处理／比较／时间，结果／单位；总效应与中介分开，局部平均≠整链，联合响应须核；历史→当前→结果，条件残差零，不等于历史无作用；对象经采集报告，才形成观测记录；量尺／分母／选择，检测／响应／保存，均可能改变趋势；保留竞争解释，用区分性材料检验，不由方向裁定原因。作者依D.03及§2.4.2绘制；数学例是条件反例，不表示现实作用大小。","caption":"作者依D.03及§2.4.2绘制；数学例是条件反例，不表示现实作用大小。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换总效应与条件残差、检出率与真实风险，显示同一记录可对应不同过程；不生成真实曲线。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"历史原始研究展示暴露分类和记录生成的具体步骤，不用经典案例名声替代识别条件。"},"openQuestions":["历史报告中的独立原始账单、化学样本和全部个案未逐项重审，案例支持限于原著所载调查过程。","全部03.01—03.09研究原稿尚未取得，不能据导航补出其结论。"],"taskId":"S-D-03","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4561—4576行；每节精确范围见sourceRefs","claim_support":["D.03：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-chain","title":"Xikari整链形式反例","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§2.4.2第307—313行，尤其第311行两类函数","claim_support":["两段平均效应各1/2但整链0的条件反例"],"limits":["数学例不估计真实世界效应。"],"access_status":"read"},{"id":"snow-formation","title":"On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855第二版；Gutenberg2024-02-07转录","locator":"1855第二版印刷pp77—80：移送后追查发病地址、供水账单/化学核验、四周未查明来源段","claim_support":["原著记述住址核对、供水分类和未查明来源的材料形成过程"],"limits":["只核指定段，不宣称重做调查或识别所有因果机制；原著转录而非原始账单全体。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-03/lecture.md","sourcesPath":"/reading-assets/S-D-03/sources.json","sourceSlicePath":"/reading-assets/S-D-03/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-03/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-03.md","filePath":"theory/appendix-d/d-03.md"}'),l={name:"theory/appendix-d/d-03.md"};function d(p,e,u,m,h,g){const t=a("SectionLesson");return r(),i("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-03" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.03</span><span class="xk-num__gap">　</span></span>研究设计、测量、因果与材料形成 <a class="header-anchor" href="#section-d-03" aria-label="Permalink to &quot;D.03　研究设计、测量、因果与材料形成 {#section-d-03}&quot;">​</a></h1><p>正文连接：§2.4—2.5；§4.1—4.6；§5.5.1；§12.3—12.7。研究入口：03.01—03.09。</p><p>随机实验、自然实验、观察研究、过程追踪、比较历史、口述与考古材料各自解决部分识别问题。先写清处理、比较对象、时间、结果和单位。被邀请者的平均效应、实际参加者的变化、整个政策的效果及某人的结果，不能只因使用同一项目名称便互相替代。</p><p>总效应不要求每一中介都已识别；有机制故事也不保证总效应成立。控制当前状态有时能排除共同原因，有时却会控制掉历史形成的通道，或打开选择偏差。H经S影响Y而给定S后H无额外信息的情形，应分开报告总作用与条件残差，不将其误作历史无效或自动满足G3。</p><p>测量要区分对象、观测指标、构念和分类规则。反映一个潜在状态的指标，与共同定义一项指数的组成项，不能使用同一效度论证。尺度、分母、测量方式与样本进入规则改变，都可能改变趋势。指标改善可以来自真实进步、狭窄训练、样本选择或记录操纵，原因须分别查，不由结果方向裁定。</p><p>教学例：申请流程简化后批准率上升，可能说明程序障碍减少；要判断生活保障是否改善，还需实际给付、服务质量与未申请者。档案中没有异议，只有在相关异议本应被稳定记录、记录得以保存且可访问的条件下，才具有相应的反证力。物质遗存的年代、用途、所有者和实际权力，同样不能由一项发现全部确定。</p><p>观测记录由对象、采集和报告过程共同形成。公开阳性记录减少，可以来自真实风险下降、响应避免结果或检出率下降；若现有材料兼容这些过程，就须保留多个解释。同一人群中两段平均作用各为正，也不足以证明整链为正：前段有效者与后段有效者可能不同。总效应、特定中介、联合响应和报告机制应针对所问问题分别识别。</p><p>专题定位：03.01 相关、因果与机制识别；03.02 实验、自然实验与观察研究；03.03 案例研究、过程追踪与比较历史；03.04 统计建模、贝叶斯更新与不确定性；03.05 测量效度与代理指标；03.06 古德哈特与坎贝尔问题；03.07 复现、发表偏差与经典实验争议；03.08 史料、档案、口述史与沉默；03.09 考古、物质文化与无文字社会。</p></div>',1)),n(t,{section:"D.03"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const b=s(l,[["render",d]]);export{f as __pageData,b as default};
